package dao;import util.Database;import java.sql.*;import java.util.*;public class TokenDAO{public String issue(String u)throws SQLException{String t=UUID.randomUUID().toString();try(Connection c=Database.open();PreparedStatement p=c.prepareStatement("INSERT INTO refresh_tokens(token_hash,user_id,expires_at) VALUES(?,?,now()+interval '7 days')")){p.setString(1,t);p.setString(2,u);p.executeUpdate();}return t;}public String user(String t)throws SQLException{try(Connection c=Database.open();PreparedStatement p=c.prepareStatement("SELECT user_id FROM refresh_tokens WHERE token_hash=? AND revoked=false AND expires_at>now()")){p.setString(1,t);try(ResultSet r=p.executeQuery()){return r.next()?r.getString(1):null;}}}public void revoke(String u)throws SQLException{try(Connection c=Database.open();PreparedStatement p=c.prepareStatement("UPDATE refresh_tokens SET revoked=true WHERE user_id=?")){p.setString(1,u);p.executeUpdate();}}}
